// 取得台北時區的日期與時間
const now = new Date();
const timezone = 'Asia/Taipei';
const dateStr = now.toLocaleDateString('zh-TW', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\//g, '-');
const timeStr = now.toLocaleTimeString('zh-TW', { timeZone: timezone, hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });

return {
  json: {
    current_date: dateStr,
    current_time: timeStr,
    timestamp: now.toISOString(),
    timezone: timezone
  }
};

// 格式化日期為所需格式
const inputData = $input.first().json;
const currentDate = inputData.current_date;
const formattedDate = currentDate.replace(/-/g, '');

return {
  json: {
    ...inputData,
    formatted_date: formattedDate,
    display_date: currentDate,
    api_date: formattedDate
  }
};

// 取得台北時區的日期與時間（確保數據可用）
const now = new Date();
const timezone = 'Asia/Taipei';
const dateStr = now.toLocaleDateString('zh-TW', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\//g, '-');
const formattedDate = dateStr.replace(/-/g, '');

// 獲取 Tableau token
const tableauAuth = $input.first().json;
let tableauToken = null;
try {
  if (tableauAuth.credentials) {
    tableauToken = tableauAuth.credentials.token || tableauAuth.credentials.sessionId;
  } else if (tableauAuth.token) {
    tableauToken = tableauAuth.token;
  }
} catch (error) {
  console.log('無法獲取 Tableau token:', error.message);
}

const TABLEAU_SITE_ID = "1b4032aa-745d-491e-93a6-847c7d77e26e";
const TABLEAU_BASE_URL = "https://prod-apnortheast-a.online.tableau.com/api/3.4";

// 數據源配置
const dataSources = [
  {
    id: "top100_player_tableau",
    name: "Top100 player",
    viewId: "73f522ea-19fd-4e62-bafb-c0abe8755ec8",
    tableauWorkbook: "Top100-player.png",
    slackChannel: "C09RUT91SPL",
    description: "Top100 player 數據處理",
    order: 1
  },
  {
    id: "top5_player_game_tableau",
    name: "Top5 player_game",
    viewId: "110c2b5c-107b-46b4-8f92-cb04f8678928",
    tableauWorkbook: "Top5-player_game.png",
    slackChannel: "C09RUT91SPL",
    description: "Top5 player_game 數據處理",
    order: 2
  }
];

// 返回處理後的數據
const results = dataSources.map((source, index) => ({
  json: {
    ...source,
    index: index + 1,
    total: dataSources.length,
    date: formattedDate,
    displayDate: dateStr,
    startTime: now.toISOString(),
    status: 'pending',
    tableauToken,
    siteId: TABLEAU_SITE_ID,
    baseUrl: TABLEAU_BASE_URL,
    retryCount: 0,
    maxRetries: 3
  }
}));

return results;

// 從前一個節點獲取數據
const viewMetadata = $input.first().json;
const sourceData = $('Process Data Sources').item.json;

// 取得今天的台北時區日期
const now = new Date();
const today = now.toLocaleDateString('zh-TW', {
  timeZone: 'Asia/Taipei',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).replace(/\//g, '-');

// 從 view metadata 中取得更新時間
let viewUpdatedAt = null;
let viewDate = null;

try {
  // Tableau API 返回的 view 對象
  if (viewMetadata.view && viewMetadata.view.updatedAt) {
    viewUpdatedAt = new Date(viewMetadata.view.updatedAt);
  } else if (viewMetadata.view && viewMetadata.view.workbook && viewMetadata.view.workbook.updatedAt) {
    // 如果 view 沒有 updatedAt，嘗試使用 workbook 的
    viewUpdatedAt = new Date(viewMetadata.view.workbook.updatedAt);
  } else if (viewMetadata.updatedAt) {
    // 直接從 metadata 取得
    viewUpdatedAt = new Date(viewMetadata.updatedAt);
  }

  if (viewUpdatedAt) {
    // 轉換為台北時區的日期
    viewDate = viewUpdatedAt.toLocaleDateString('zh-TW', {
      timeZone: 'Asia/Taipei',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).replace(/\//g, '-');
  }
} catch (error) {
  console.log('解析 view 更新時間失敗:', error.message);
}

// 判斷是否是今天的數據
const isToday = viewDate === today;
const retryCount = sourceData.retryCount || 0;
const maxRetries = sourceData.maxRetries || 3;
const canRetry = retryCount < maxRetries;

// 記錄檢查資訊
console.log(`[${sourceData.name}] 日期檢查:`);
console.log(`  今天: ${today}`);
console.log(`  數據日期: ${viewDate || '無法取得'}`);
console.log(`  重試次數: ${retryCount}/${maxRetries}`);
console.log(`  是今天: ${isToday}`);

return {
  json: {
    ...sourceData,
    viewMetadata: viewMetadata.view || viewMetadata,
    viewUpdatedAt: viewUpdatedAt ? viewUpdatedAt.toISOString() : null,
    viewDate,
    today,
    isToday,
    retryCount,
    maxRetries,
    canRetry,
    checkTime: now.toISOString(),
    message: isToday
      ? `✅ 數據已更新到今天 (${today})`
      : `⚠️ 數據仍是 ${viewDate || '未知日期'}，今天是 ${today}`
  }
};

const currentData = $input.first().json;
const newRetryCount = (currentData.retryCount || 0) + 1;

console.log(`[${currentData.name}] 重試次數: ${currentData.retryCount} → ${newRetryCount}`);

return {
  json: {
    ...currentData,
    retryCount: newRetryCount,
    lastRetryTime: new Date().toISOString()
  }
};

